g[24].append(4); H,W=len(g),17; comps=[]; seen=set()
for r in range(H):
 for c in range(W):
  col=g[r][c]
  if col==4 or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c)); cells=[]
  while q:
   x,y=q.pop();cells.append((x,y))
   for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
    if 0<=a<H and 0<=b<W and g[a][b]==col and (a,b) not in seen:
     seen.add((a,b));q.append((a,b))
  comps.append((col,cells))
for i,(col,cells) in enumerate(comps): print(i,col,len(cells),(min(r for r,c in cells),max(r for r,c in cells),min(c for r,c in cells),max(c for r,c in cells)),sorted(cells))
